1	//! Git access by shelling the real `git` binary through a
2	//! [`crate::CommandRunner`].
3	
4	use std::path::{Path, PathBuf};
5	
6	use crate::release_pr::REGULAR_FILE_MODE;
7	use crate::{ApplyPermit, CommandOutput, CommandRunner, CommitSha, StagedChangeKindV1, StagedChangeV1, TagName};
8	
9	use crate::vcs::{GitCommit, GitStdout, LogEntry, Pathspec, TagSignPolicy, VcsError};
10	
11	/// Every Git read and write callisto performs, each one `git` subprocess
12	/// run in `root` through a [`CommandRunner`].
13	pub struct GitAccess<'r> {
14	    runner: &'r dyn CommandRunner,
15	    root: PathBuf,
16	}
17	
18	/// The first-parent commits that changed each of a set of paths, from one `git log`.
19	#[derive(Debug, Default)]
20	pub struct FirstParentTouches {
21	    /// Every commit that changed any of the paths, newest first.
22	    commits: Vec<String>,
23	    /// For each path, the positions in `commits` of the commits that changed it, ascending.
24	    by_path: std::collections::BTreeMap<PathBuf, Vec<usize>>,
25	}
26	
27	impl FirstParentTouches {
28	    /// The commits that changed any of `paths`, newest first.
29	    pub fn touching(&self, paths: &[PathBuf]) -> Vec<&str> {
30	        let positions: std::collections::BTreeSet<usize> = paths
31	            .iter()
32	            .filter_map(|path| self.by_path.get(path))
33	            .flatten()
34	            .copied()
35	            .collect();
36	        positions
37	            .into_iter()
38	            .map(|index| self.commits[index].as_str())
39	            .collect()
40	    }
41	}
42	
43	/// Fresh Git checkout facts used to bind a durable release intent to the
44	/// exact repository it was validated against.
45	///
46	/// This is intentionally evidence, not a lossy `bool`: consumers must retain
47	/// the canonical root and complete `HEAD` they compare to source identity.
48	/// Its fields are private so only the VCS observation path can construct it.
49	#[derive(Debug, PartialEq, Eq)]
50	pub struct GitCommitTrustEvidence {
51	    canonical_root: PathBuf,
52	    head: CommitSha,
53	    head_disposition: GitHeadDisposition,
54	}
55	
56	impl GitCommitTrustEvidence {
57	    pub(crate) fn new(canonical_root: PathBuf, head: CommitSha, head_disposition: GitHeadDisposition) -> Self {
58	        Self {
59	            canonical_root,
60	            head,
61	            head_disposition,
62	        }
63	    }
64	
65	    pub fn canonical_root(&self) -> &Path {
66	        &self.canonical_root
67	    }
68	
69	    pub fn head(&self) -> &CommitSha {
70	        &self.head
71	    }
72	
73	    pub fn head_disposition(&self) -> GitHeadDisposition {
74	        self.head_disposition
75	    }
76	}
77	
78	/// Whether `HEAD` was attached to a symbolic reference when it was observed.
79	/// A detached checkout is valid when its full [`CommitSha`] matches the
80	/// release intent's source identity.
81	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
82	pub enum GitHeadDisposition {
83	    Attached,
84	    Detached,
85	}
86	
87	impl<'r> GitAccess<'r> {
88	    pub fn new(root: impl Into<PathBuf>, runner: &'r dyn CommandRunner) -> Self {
89	        GitAccess {
90	            runner,
91	            root: root.into(),
92	        }
93	    }
94	
95	    /// Every staged (index) change relative to `base`, resolved from the repository's toplevel rather than
96	    /// `self.root` so this works from any subdirectory. Worktree bytes are read directly (for CRLF/binary
97	    /// fidelity) and verified against the index blob sha; a mismatch fails loudly instead of returning stale bytes.
98	    pub fn staged_changes_since(&self, base: &CommitSha) -> Result<Vec<StagedChangeV1>, VcsError> {
99	        let root = self.repo_root()?;
100	
101	        // Quiet for the same reason: a failure is returned below with git's message.
102	        let output = self.runner.run_quiet(
103	            "git",
104	            &[
105	                "diff",
106	                "--cached",
107	                "--raw",
108	                "-z",
109	                "--no-renames",
110	                "--no-abbrev",
111	                base.as_str(),
112	            ],
113	            &root,
114	            crate::LOCAL_GIT_TIMEOUT,
115	        )?;
116	        let output = GitStdout::of(output).map_err(|output| {
117	            VcsError::Git(format!(
118	                "`git diff --cached --raw` against `{}` failed: {}",
119	                base.as_str(),
120	                output.redacted_stderr()
121	            ))
122	        })?;
123	
124	        let entries = parse_raw_diff_z(&output)?;
125	        let mut changes = Vec::with_capacity(entries.len());
126	        for entry in entries {
127	            let kind = staged_change_kind(entry.status);
128	            let contents = match kind {
129	                // Any other mode gets no contents so the commit plan rejects it before a symlink or submodule is read.
130	                StagedChangeKindV1::Added | StagedChangeKindV1::Modified
131	                    if entry.new_mode == Some(REGULAR_FILE_MODE) =>
132	                {
133	                    let bytes = std::fs::read(root.join(&entry.path)).map_err(|error| {
134	                        VcsError::Git(format!("could not read staged file `{}`: {error}", entry.path))
135	                    })?;
136	                    self.verify_staged_blob(&root, &entry.path, &entry.new_sha)?;
137	                    Some(bytes)
138	                }
139	                _ => None,
140	            };
141	            changes.push(StagedChangeV1 {
142	                path: entry.path,
143	                kind,
144	                new_mode: entry.new_mode,
145	                contents,
146	            });
147	        }
148	        Ok(changes)
149	    }
150	
151	    /// Resolves the repository's toplevel directory, whether `self.root` is that toplevel or a subdirectory.
152	    fn repo_root(&self) -> Result<PathBuf, VcsError> {
153	        self.resolved_toplevel(&format!("in `{}`", self.root.display()))
154	    }
155	
156	    /// The repository's toplevel directory, via `git rev-parse --show-toplevel` -- honors
157	    /// `GIT_DIR`/`GIT_WORK_TREE`/`GIT_CEILING_DIRECTORIES` the way `git` itself does, unlike a
158	    /// hand-rolled walk up the filesystem looking for a `.git` entry.
159	    pub fn toplevel(&self) -> Result<PathBuf, VcsError> {
160	        self.repo_root()
161	    }
162	
163	    /// The `git rev-parse --show-toplevel` resolution shared by every caller; `context` names the caller on failure.
164	    fn resolved_toplevel(&self, context: &str) -> Result<PathBuf, VcsError> {
165	        // Quiet: the failure is returned below with git's message, so echoing it as well prints it twice.
166	        let output = self.runner.run_quiet(
167	            "git",
168	            &["rev-parse", "--show-toplevel"],
169	            &self.root,
170	            crate::LOCAL_GIT_TIMEOUT,
171	        )?;
172	        let output = GitStdout::of(output).map_err(|output| {
173	            VcsError::Git(format!(
174	                "could not determine the Git repository root {context}: {}",
175	                output.redacted_stderr()
176	            ))
177	        })?;
178	        canonical_git_root(&output.path())
179	    }
180	
181	    /// Confirms the worktree bytes just read for `path` hash to the same blob sha the index has staged, without
182	    /// round-tripping content through a lossy `String` capture. Filters are skipped so the hash covers the bytes
183	    /// that are sent, not their clean-filtered form.
184	    fn verify_staged_blob(&self, root: &Path, path: &str, expected_sha: &str) -> Result<(), VcsError> {
185	        let output = self
186	            .runner
187	            .run("git", &["hash-object", "--no-filters", "--", path], root)?;
188	        if !output.success() {
189	            return Err(VcsError::Git(format!(
190	                "`git hash-object` failed for `{path}` in `{}`: {}",
191	                root.display(),
192	                output.redacted_stderr()
193	            )));
194	        }
195	        let actual_sha = output.stdout_trimmed();
196	        if actual_sha != expected_sha {
197	            return Err(VcsError::StagedContentMismatch {
198	                path: path.to_string(),
199	                expected_sha: expected_sha.to_string(),
200	            });
201	        }
202	        Ok(())
203	    }
204	
205	    /// The two repository-wide conditions release trust needs: the SHA-1 object format (E265) and the whole history
206	    /// (E266). Every release route checks them before it reads a commit, so none reports a lower-level git failure instead.
207	    pub fn require_trustable_repository(&self) -> Result<(), VcsError> {
208	        let object_format = self
209	            .runner
210	            .run("git", &["rev-parse", "--show-object-format"], &self.root)?;
211	        if !object_format.success() || object_format.stdout_trimmed() != "sha1" {
212	            return Err(VcsError::UnsupportedObjectFormat {
213	                found: object_format.stdout_trimmed().to_string(),
214	            });
215	        }
216	        if !self.has_full_history()? {
217	            return Err(VcsError::ShallowRepository);
218	        }
219	        Ok(())
220	    }
221	
222	    /// Returns explicit, fresh Git trust evidence for a durable release.
223	    /// Errors omit raw stderr; ignored paths (build output) are allowed.
224	    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
225	        let canonical_root = self.resolved_toplevel("for release trust")?;
226	        self.require_trustable_repository()?;
227	
228	        let head = self
229	            .runner
230	            .run("git", &["rev-parse", "--verify", "HEAD^{commit}"], &self.root)?;
231	        if !head.success() {
232	            return Err(VcsError::Git(
233	                "could not resolve a commit for release trust".to_string(),
234	            ));
235	        }
236	        let head = CommitSha::parse(head.stdout_trimmed()).map_err(|error| VcsError::InvalidCommitSha {
237	            context: "for release trust".to_string(),
238	            message: error.to_string(),
239	        })?;
240	
241	        let symbolic_head = self
242	            .runner
243	            .run("git", &["symbolic-ref", "--quiet", "HEAD"], &self.root)?;
244	        let head_disposition = match symbolic_head.exit_code {
245	            Some(0) => GitHeadDisposition::Attached,
246	            Some(1) => GitHeadDisposition::Detached,
247	            _ => {
248	                return Err(VcsError::Git(
249	                    "could not determine the symbolic HEAD state for release trust".to_string(),
250	                ))
251	            }
252	        };
253	
254	        let status = self.runner.run(
255	            "git",
256	            &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
257	            &self.root,
258	        )?;
259	        let Ok(status) = GitStdout::of(status) else {
260	            return Err(VcsError::Git(
261	                "could not inspect the worktree for release trust".to_string(),
262	            ));
263	        };
264	        check_release_worktree_status(&status)?;
265	
266	        Ok(GitCommitTrustEvidence::new(canonical_root, head, head_disposition))
267	    }
268	}
269	
270	/// One `git diff --raw -z` record, before Git's single-letter status is
271	/// mapped to a [`StagedChangeKindV1`] and file contents are read.
272	struct RawDiffEntry {
273	    path: String,
274	    /// The post-image Git file mode, or `None` for a pure deletion.
275	    new_mode: Option<u32>,
276	    /// The post-image blob sha staged for this path, verified against a worktree read in `verify_staged_blob`.
277	    new_sha: String,
278	    status: char,
279	}
280	
281	/// Parses `git diff --raw -z --no-renames` output. Each record is two
282	/// `\0`-separated tokens: a `:<old-mode> <new-mode> <old-sha> <new-sha>
283	/// <status>` metadata line, then the path. `--no-renames` guarantees at
284	/// most one path per record (a rename or copy would otherwise emit two).
285	fn parse_raw_diff_z(raw: &GitStdout) -> Result<Vec<RawDiffEntry>, VcsError> {
286	    let mut entries = Vec::new();
287	    let mut tokens = raw.fields();
288	    while let Some(meta) = tokens.next() {
289	        let Some(meta) = meta.strip_prefix(':') else {
290	            return Err(VcsError::MalformedDiffOutput {
291	                detail: format!("unexpected token, expected a metadata line starting with `:`: {meta:?}"),
292	            });
293	        };
294	        let path = tokens.next().ok_or_else(|| VcsError::MalformedDiffOutput {
295	            detail: "truncated output: missing a path after its metadata line".to_string(),
296	        })?;
297	        let fields: Vec<&str> = meta.split(' ').collect();
298	        let [_old_mode, new_mode, _old_sha, new_sha, status_field] = fields.as_slice() else {
299	            return Err(VcsError::MalformedDiffOutput {
300	                detail: format!("malformed metadata line: {meta:?}"),
301	            });
302	        };
303	        let status = status_field
304	            .chars()
305	            .next()
306	            .ok_or_else(|| VcsError::MalformedDiffOutput {
307	                detail: format!("empty status in metadata line: {meta:?}"),
308	            })?;
309	        let new_mode = if status == 'D' {
310	            None
311	        } else {
312	            Some(
313	                u32::from_str_radix(new_mode, 8).map_err(|error| VcsError::MalformedDiffOutput {
314	                    detail: format!("invalid Git mode `{new_mode}`: {error}"),
315	                })?,
316	            )
317	        };
318	        entries.push(RawDiffEntry {
319	            path: path.to_string(),
320	            new_mode,
321	            new_sha: (*new_sha).to_string(),
322	            status,
323	        });
324	    }
325	    Ok(entries)
326	}
327	
328	/// Maps a `git diff --raw` single-letter status to a [`StagedChangeKindV1`].
329	/// Any status this codebase does not have a named case for (Git's own docs
330	/// list `X` as "unknown") conservatively maps to `Unmerged`, which
331	/// [`crate::ReleasePrCommitPlanV1::from_changes`] always rejects --
332	/// safe by construction rather than by an exhaustive status list here.
333	fn staged_change_kind(status: char) -> StagedChangeKindV1 {
334	    match status {
335	        'A' => StagedChangeKindV1::Added,
336	        'M' => StagedChangeKindV1::Modified,
337	        'D' => StagedChangeKindV1::Deleted,
338	        'R' => StagedChangeKindV1::Renamed,
339	        'C' => StagedChangeKindV1::Copied,
340	        'T' => StagedChangeKindV1::TypeChanged,
341	        _ => StagedChangeKindV1::Unmerged,
342	    }
343	}
344	
345	fn canonical_git_root(raw_root: &Path) -> Result<PathBuf, VcsError> {
346	    if raw_root.as_os_str().is_empty() {
347	        return Err(VcsError::InvalidRepositoryRoot {
348	            detail: "Git returned an empty repository root".to_string(),
349	        });
350	    }
351	    dunce::canonicalize(raw_root).map_err(|error| VcsError::InvalidRepositoryRoot {
352	        detail: format!("could not canonicalize `{}`: {error}", raw_root.display()),
353	    })
354	}
355	
356	/// Ignored paths are build output and never block; tracked or untracked changes do.
357	fn check_release_worktree_status(status: &GitStdout) -> Result<(), VcsError> {
358	    match status.fields().next() {
359	        None => Ok(()),
360	        Some(record) => Err(VcsError::DirtyWorktree {
361	            path: record.get(3..).unwrap_or(record).to_string(),
362	        }),
363	    }
364	}
365	
366	/// A Git probe that failed for a reason other than "the thing asked about is absent".
367	fn probe_failed(args: &[&str], root: &Path, output: &CommandOutput) -> VcsError {
368	    VcsError::Git(format!(
369	        "`git {}` failed in `{}`: {}",
370	        args.join(" "),
371	        root.display(),
372	        output.redacted_stderr()
373	    ))
374	}
375	
376	impl GitAccess<'_> {
377	    /// Returns the commit SHA that `HEAD` currently resolves to.
378	    pub fn head_sha(&self) -> Result<CommitSha, VcsError> {
379	        let output = self.runner.run("git", &["rev-parse", "HEAD"], &self.root)?;
380	        if !output.success() {
381	            return Err(VcsError::Git(format!(
382	                "`git rev-parse HEAD` failed in `{}`: {}",
383	                self.root.display(),
384	                output.redacted_stderr()
385	            )));
386	        }
387	        let sha_str = output.stdout_trimmed();
388	        CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
389	            context: format!("in `git rev-parse HEAD` output `{sha_str}`"),
390	            message: e.to_string(),
391	        })
392	    }
393	
394	    /// The committer time of `rev` in whole seconds since the epoch.
395	    pub fn commit_time(&self, rev: &str) -> Result<u64, VcsError> {
396	        let output = self.runner.run(
397	            "git",
398	            &["show", "-s", "--no-show-signature", "--format=%ct", rev],
399	            &self.root,
400	        )?;
401	        let stdout = output.stdout_trimmed();
402	        match stdout.parse::<u64>() {
403	            Ok(seconds) if output.success() => Ok(seconds),
404	            _ => Err(VcsError::Git(format!(
405	                "`git show -s --no-show-signature --format=%ct {rev}` failed in `{}`: {}",
406	                self.root.display(),
407	                output.redacted_stderr()
408	            ))),
409	        }
410	    }
411	
412	    /// Whether `path` (relative to this root) exists in `rev`'s tree; a revision that does not resolve has no paths.
413	    pub fn path_exists_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
414	        let spec = format!("{rev}:./{}", path.display());
415	        let args = ["rev-parse", "--verify", "--quiet", &spec];
416	        let output = self.runner.run("git", &args, &self.root)?;
417	        if output.success() {
418	            return Ok(true);
419	        }
420	        if output.exit_code == Some(1) {
421	            return Ok(false);
422	        }
423	        Err(probe_failed(&args, &self.root, &output))
424	    }
425	
426	    /// Files in `rev`'s tree matching one of `pathspecs` whose text contains `needle`, ignoring case.
427	    ///
428	    /// No match is an empty list; a revision that cannot be searched is an error.
429	    pub fn files_containing_at(
430	        &self,
431	        rev: &str,
432	        needle: &str,
433	        pathspecs: &[Pathspec],
434	    ) -> Result<Vec<PathBuf>, VcsError> {
435	        let mut args = vec!["grep", "-l", "-z", "-F", "-i", "-e", needle, rev, "--"];
436	        args.extend(pathspecs.iter().map(Pathspec::as_str));
437	        let output = self.runner.run("git", &args, &self.root)?;
438	        if output.exit_code == Some(1) {
439	            return Ok(Vec::new());
440	        }
441	        let output = GitStdout::of(output).map_err(|output| probe_failed(&args, &self.root, &output))?;
442	        let prefix = format!("{rev}:");
443	        Ok(output
444	            .fields()
445	            .filter_map(|entry| entry.strip_prefix(&prefix))
446	            .map(PathBuf::from)
447	            .collect())
448	    }
449	
450	    /// The text of `path` (relative to this root) in `rev`'s tree, decoded lossily; `None` when it is absent.
451	    pub fn read_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
452	        if !self.path_exists_at(rev, path)? {
453	            return Ok(None);
454	        }
455	        let spec = format!("{rev}:./{}", path.display());
456	        let args = ["show", &spec];
457	        let output = GitStdout::of(self.runner.run("git", &args, &self.root)?)
458	            .map_err(|output| probe_failed(&args, &self.root, &output))?;
459	        Ok(Some(output.into_text()))
460	    }
461	
462	    /// The most recent commit that added `path`, if it is committed.
463	    pub fn commit_adding(&self, path: &Path) -> Result<Option<String>, VcsError> {
464	        // A repository with no commits has no history to search; `git log` would fail there.
465	        if self.resolve_commit("HEAD")?.is_none() {
466	            return Ok(None);
467	        }
468	        let path = Pathspec::literal(path);
469	        let args = [
470	            "log",
471	            "--no-show-signature",
472	            "--diff-filter=A",
473	            "--format=%H",
474	            "-1",
475	            "--",
476	            path.as_str(),
477	        ];
478	        let output = self.runner.run("git", &args, &self.root)?;
479	        if !output.success() {
480	            return Err(probe_failed(&args, &self.root, &output));
481	        }
482	        let sha = output.stdout_trimmed();
483	        Ok((!sha.is_empty()).then(|| sha.to_string()))
484	    }
485	
486	    /// The commits on HEAD's first-parent line that changed `pathspecs`, newest first. A merge commit counts when
487	    /// it changes them relative to its first parent, so a squash or merge landing a release is one entry.
488	    pub fn first_parent_commits_touching(&self, pathspecs: &[PathBuf]) -> Result<Vec<String>, VcsError> {
489	        let mut args: Vec<String> = ["log", "--no-show-signature", "--first-parent", "--format=%H", "--"]
490	            .map(str::to_owned)
491	            .into();
492	        args.extend(pathspecs.iter().map(|path| Pathspec::literal(path).as_str().to_owned()));
493	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
494	        let output = GitStdout::of(self.runner.run("git", &arg_refs, &self.root)?)
495	            .map_err(|output| probe_failed(&arg_refs, &self.root, &output))?;
496	        Ok(output.lines().map(str::to_owned).collect())
497	    }
498	
499	    /// [`Self::first_parent_commits_touching`] for many paths in one `git log`, so each path's commits cost no process
500	    /// of their own.
501	    pub fn first_parent_commits_by_path(&self, paths: &[PathBuf]) -> Result<FirstParentTouches, VcsError> {
502	        let mut touches = FirstParentTouches::default();
503	        if paths.is_empty() {
504	            return Ok(touches);
505	        }
506	        // `-z` keeps odd file names unquoted and frames each commit's id and files with NUL.
507	        let mut args: Vec<String> = [
508	            "log",
509	            "--no-show-signature",
510	            "--first-parent",
511	            "-m",
512	            "--root",
513	            "-z",
514	            "--name-only",
515	            "--relative",
516	            &LogEntry::format("%H"),
517	            "--",
518	        ]
519	        .map(str::to_owned)
520	        .into();
521	        args.extend(paths.iter().map(|path| Pathspec::literal(path).as_str().to_owned()));
522	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
523	        let output = self.runner.run("git", &arg_refs, &self.root)?;
524	        let output = GitStdout::of(output).map_err(|output| probe_failed(&arg_refs, &self.root, &output))?;
525	        for entry in output.log_entries()? {
526	            let index = touches.commits.len();
527	            touches.commits.push(entry.header.to_owned());
528	            for file in entry.files {
529	                touches.by_path.entry(PathBuf::from(file)).or_default().push(index);
530	            }
531	        }
532	        Ok(touches)
533	    }
