559	    pub fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
560	        let output = GitStdout::of(self.runner.run("git", &["tag", "--list"], &self.root)?)
561	            .map_err(|output| probe_failed(&["tag", "--list"], &self.root, &output))?;
562	        let all = output.lines();
563	
564	        let matcher = glob.map(crate::vcs::compile_tag_glob).transpose()?;
565	
566	        Ok(all
567	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
568	            // A legal Git ref is not necessarily safe as a bare CLI positional (a leading `-`).
569	            .filter_map(|t| TagName::parse(t).ok())
570	            .collect())
571	    }
