573	    /// Every tag with the commit it ends at, from one `git for-each-ref`. The commit is `None` when the tag ends at
574	    /// something else (a tree, a blob, a tag of a tag), which [`Self::resolve_commit`] then decides.
575	    pub fn tags_with_commits(&self) -> Result<Vec<(TagName, Option<CommitSha>)>, VcsError> {
576	        let args = [
577	            "for-each-ref",
578	            "--format=%(refname:strip=2)%00%(objecttype)%00%(objectname)%00%(*objecttype)%00%(*objectname)",
579	            "refs/tags",
580	        ];
581	        let output = GitStdout::of(self.runner.run("git", &args, &self.root)?)
582	            .map_err(|output| probe_failed(&args, &self.root, &output))?;
583	        Ok(output
584	            .lines()
585	            .filter_map(|line| {
586	                let mut fields = line.split('\0');
587	                let name = TagName::parse(fields.next()?).ok()?;
588	                let (kind, object, peeled_kind, peeled) =
589	                    (fields.next()?, fields.next()?, fields.next()?, fields.next()?);
590	                let commit = match (kind, peeled_kind) {
591	                    ("commit", _) => CommitSha::parse(object).ok(),
592	                    ("tag", "commit") => CommitSha::parse(peeled).ok(),
593	                    _ => None,
594	                };
595	                Some((name, commit))
596	            })
597	            .collect())
598	    }
