610	    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
611	    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
612	    /// callers treat as "no bound" / "infer over full history".
613	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
614	        let rev = format!("{refname}^{{commit}}");
615	        let args = ["rev-parse", "--verify", "--quiet", &rev];
616	        let output = self.runner.run("git", &args, &self.root)?;
617	
618	        if output.exit_code == Some(1) {
619	            return Ok(None);
620	        }
621	        if !output.success() {
622	            return Err(probe_failed(&args, &self.root, &output));
623	        }
624	        let sha_str = output.stdout_trimmed();
625	        if sha_str.is_empty() {
626	            return Ok(None);
627	        }
628	        Ok(CommitSha::parse(sha_str).ok())
629	    }
