631	    /// Lists non-merge commits reachable from `HEAD`, down to (exclusive)
632	    /// `since_ref` when given, keeping those that touch at least one of
633	    /// `pathspecs` (empty keeps every commit).
634	    ///
635	    /// `--full-history`: a commit touching a pathspec counts even when a
636	    /// later merge discarded its change (e.g. `merge -s ours`); default
637	    /// history simplification would silently drop it.
638	    ///
639	    /// A `since_ref` that is given but does not resolve is
640	    /// [`VcsError::RefNotFound`], never a silent unbounded walk.
641	    pub fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
642	        let mut args: Vec<String> = vec![
643	            "log".to_string(),
644	            "--no-show-signature".to_string(),
645	            "--no-merges".to_string(),
646	            "--full-history".to_string(),
647	            "-z".to_string(),
648	            "--format=%H%n%B".to_string(),
649	        ];
650	
651	        match since_ref {
652	            Some(r) => args.push(format!("{r}..HEAD")),
653	            None => args.push("HEAD".to_string()),
654	        }
655	
656	        if !pathspecs.is_empty() {
657	            args.push("--".to_string());
658	            args.extend(pathspecs.iter().map(|p| Pathspec::literal(p).as_str().to_owned()));
659	        }
660	
661	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
662	        let output = match GitStdout::of(self.runner.run("git", &arg_refs, &self.root)?) {
663	            Ok(output) => output,
664	            Err(output) => {
665	                if let Some(r) = since_ref
666	                    && self.resolve_commit(r)?.is_none()
667	                {
668	                    return Err(VcsError::RefNotFound {
669	                        ref_name: r.to_string(),
670	                    });
671	                }
672	                if self.head_is_unborn() {
673	                    return Ok(Vec::new());
674	                }
675	                return Err(VcsError::Git(format!(
676	                    "`git log` failed in `{}`: {}",
677	                    self.root.display(),
678	                    output.redacted_stderr()
679	                )));
680	            }
681	        };
682	
683	        parse_git_log_output(&output, &self.root)
684	    }
