717	    /// The object id each `<revision>:<path>` names, `None` for one that names nothing, from one `git cat-file
718	    /// --batch-check`. An empty path names the revision's root tree. Two specs name the same content exactly when their
719	    /// ids are equal, so this compares directories at two commits without reading either.
720	    pub fn object_ids(&self, specs: &[String]) -> Result<Vec<Option<String>>, VcsError> {
721	        if specs.is_empty() {
722	            return Ok(Vec::new());
723	        }
724	        let args = ["cat-file", "--batch-check"];
725	        let stdin = specs.join("\n") + "\n";
726	        let output = GitStdout::of(self.runner.run_with_stdin("git", &args, &self.root, stdin.as_bytes())?)
727	            .map_err(|output| probe_failed(&args, &self.root, &output))?;
728	        let malformed = |detail: String| VcsError::MalformedLogOutput {
729	            detail: format!("in `{}`: {detail}", self.root.display()),
730	        };
731	        let lines: Vec<&str> = output.lines().collect();
732	        if lines.len() != specs.len() {
733	            return Err(malformed(format!(
734	                "`git cat-file --batch-check` answered {} lines for {} objects",
735	                lines.len(),
736	                specs.len()
737	            )));
738	        }
739	        specs
740	            .iter()
741	            .zip(lines)
742	            .map(|(spec, line)| {
743	                if line.strip_prefix(spec.as_str()) == Some(" missing") {
744	                    return Ok(None);
745	                }
746	                match line.split(' ').next() {
747	                    Some(id) if CommitSha::parse(id).is_ok() => Ok(Some(id.to_owned())),
748	                    _ => Err(malformed(format!("`{spec}` was answered with `{line}`"))),
749	                }
750	            })
751	            .collect()
752	    }
