754	    fn name_only(&self, args: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
755	        let output = GitStdout::of(self.runner.run("git", args, &self.root)?).map_err(|output| {
756	            VcsError::Git(format!(
757	                "`git {}` failed in `{}`: {}",
758	                args[0],
759	                self.root.display(),
760	                output.redacted_stderr()
761	            ))
762	        })?;
763	        Ok(output.fields().map(PathBuf::from).collect())
764	    }
