766	    /// Creates the tag `name` at `target_sha`: annotated with `message`
767	    /// when `Some`, lightweight when `None`. Fails if the tag already
768	    /// exists. Writes a ref, so it requires an [`ApplyPermit`].
769	    pub fn create_tag(
770	        &self,
771	        name: &str,
772	        target_sha: &CommitSha,
773	        message: Option<&str>,
774	        sign: TagSignPolicy,
775	        _permit: &ApplyPermit,
776	    ) -> Result<(), VcsError> {
777	        let identity = match message {
778	            Some(_) => self.tagger_identity_override(target_sha)?,
779	            None => None,
780	        };
781	        let mut args: Vec<&str> = Vec::new();
782	        if let Some([name_config, email_config]) = &identity {
783	            args.extend(["-c", name_config.as_str(), "-c", email_config.as_str()]);
784	        }
785	        // `--` ends option parsing so `name` can never be misread as a flag.
786	        args.push("tag");
787	        if let Some(msg) = message {
788	            args.extend(["-a", "-m", msg]);
789	        }
790	        if matches!(sign, TagSignPolicy::ForceUnsigned) {
791	            args.push("--no-sign");
792	        }
793	        args.extend(["--", name, target_sha.as_str()]);
794	        let output = self.runner.run("git", &args, &self.root)?;
795	        if !output.success() {
796	            return Err(VcsError::Git(format!(
797	                "`git tag` failed in `{}`: {}",
798	                self.root.display(),
799	                output.redacted_stderr()
800	            )));
801	        }
802	        Ok(())
803	    }
