805	    /// `None` when Git can resolve a committer identity itself. Otherwise the
806	    /// target commit's committer, as `-c` overrides, since an annotated tag
807	    /// needs a tagger and a release runner's checkout often configures none.
808	    fn tagger_identity_override(&self, target_sha: &CommitSha) -> Result<Option<[String; 2]>, VcsError> {
809	        let ident = self.runner.run("git", &["var", "GIT_COMMITTER_IDENT"], &self.root)?;
810	        if ident.success() {
811	            return Ok(None);
812	        }
813	        let commit = self
814	            .runner
815	            .run("git", &["cat-file", "commit", target_sha.as_str()], &self.root)?;
816	        let committer = commit
817	            .stdout
818	            .lines()
819	            .take_while(|line| !line.is_empty())
820	            .find_map(|line| line.strip_prefix("committer "))
821	            .and_then(|ident| ident.split_once(" <"))
822	            .and_then(|(name, rest)| Some((name, rest.split_once('>')?.0)));
823	        match committer {
824	            Some((name, email)) if commit.success() && !name.is_empty() && !email.is_empty() => {
825	                Ok(Some([format!("user.name={name}"), format!("user.email={email}")]))
826	            }
827	            _ => Err(VcsError::Git(format!(
828	                "no Git identity for the tagger and could not read the committer of `{}`: {}",
829	                target_sha.as_str(),
830	                commit.redacted_stderr()
831	            ))),
832	        }
833	    }
834	}
