836	/// Parses the `-z --format=%H%n%B` `git log` output produced by [`GitAccess::commits_since`] into [`GitCommit`]s,
837	/// splitting each raw message on its first blank line into `summary`/`body`.
838	fn parse_git_log_output(stdout: &GitStdout, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
839	    let mut commits = Vec::new();
840	
841	    for record in stdout.fields() {
842	        // Split before trimming: an empty message leaves `<sha>\n`, which is a commit, not a malformed record.
843	        let Some((sha_str, message)) = record.split_once('\n') else {
844	            return Err(VcsError::MalformedLogOutput {
845	                detail: format!(
846	                    "in `{}`: expected a `<sha>\\n<message>` record, got: {record:?}",
847	                    cwd.display()
848	                ),
849	            });
850	        };
851	
852	        let sha = CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
853	            context: format!("in `git log` output in `{}`", cwd.display()),
854	            message: e.to_string(),
855	        })?;
856	
857	        let message = message.trim_end_matches('\n').replace("\r\n", "\n");
858	        let (summary, body) = match message.split_once("\n\n") {
859	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
860	            None => (message.trim_end().to_string(), None),
861	        };
862	
863	        commits.push(GitCommit { sha, summary, body });
864	    }
865	
866	    Ok(commits)
867	}
