    #[test]
    fn a_local_rev_parse_without_an_exit_code_or_with_output_on_failure_is_not_an_absent_tag() {
        for script in [
            ScriptedRevParse {
                exit_code: None,
                stdout: "",
                stderr: "",
            },
            ScriptedRevParse {
                exit_code: Some(1),
                stdout: "unexpected\n",
                stderr: "",
            },
            ScriptedRevParse {
                exit_code: Some(2),
                stdout: "",
                stderr: "",
            },
