fn default_branch_keeps_slashes_from_every_source() {
    let dir = workspace();
    git(dir.path(), &["branch", "release/next"]);
    git(
        dir.path(),
        &[
            "symbolic-ref",
            "refs/remotes/origin/HEAD",
            "refs/remotes/origin/release/next",
        ],
    );
