    // An unreadable remote reports nothing, and git's own error never reaches the terminal.
    #[test]
    fn the_origin_tag_probe_is_quiet_when_the_remote_cannot_be_read() {
        let probe = OriginTagProbe {
            endpoint: "https://example.invalid/r.git".to_owned(),
            cwd: std::path::PathBuf::from("."),
            tags: std::collections::BTreeSet::from(["a@1.0.0".to_owned()]),
        };
        let runner = UnreachableRemote {
            used_live_echo: std::sync::atomic::AtomicBool::new(false),
        };
        assert!(probe.missing(&runner).is_empty());
        assert!(
            !runner.used_live_echo.load(std::sync::atomic::Ordering::SeqCst),
            "the probe must use run_quiet, not the live-echoing run_with_timeout"
        );
    }

    fn git(root: &Path, args: &[&str]) {
        assert!(std::process::Command::new("git")
            .args(args)
            .current_dir(root)
            .status()
            .unwrap()
            .success());

// Neither local nor remote resolves a HEAD: falls back to the branch checked out.
#[test]
fn default_branch_falls_back_to_the_current_branch() {
    let dir = workspace();
    git(dir.path(), &["checkout", "-q", "-b", "release"]);
    let resolved = default_branch(&StubRemoteHead { remote_head: None }, dir.path(), origin(dir.path()).as_ref());
    assert_eq!(resolved.name.as_str(), "release");
    assert_eq!(resolved.source, DefaultBranchSource::CurrentBranch);
}

// No git repository at all: nothing resolves, so `main` is the last resort.
#[test]
fn default_branch_falls_back_to_main_when_nothing_resolves() {
    let none = tempfile::tempdir().unwrap();
    let resolved = default_branch(&RealGitRunner, none.path());
    assert_eq!(resolved.name.as_str(), "main");
    assert_eq!(resolved.source, DefaultBranchSource::Fallback);
}

