fn remote_urls(&self, args: &[&str]) -> Result<Option<Vec<String>>, VcsError> {
    // Quiet: a missing remote is an answer, so git's own "No such remote" must not reach the terminal.
    let output = self.runner().run_quiet("git", args, self.root(), crate::LOCAL_GIT_TIMEOUT)?;
    if output.exit_code == Some(2) {
        return Ok(None);
    }
    let output = GitStdout::of(output).map_err(|output| {
        VcsError::Git(format!("`git {}` failed: {}", args.join(" "), output.redacted_stderr()))
    })?;
    Ok(Some(output.lines().map(str::to_owned).collect()))
}

