fn run_with_timeout_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    echo: LiveEcho,
    live_secrets: Vec<String>,
    child_env: ChildEnvironment<'_>,
) -> Result<CommandOutput, CommandError> {
    let mut command = std::process::Command::new(program);
    command
        .args(args)
        .current_dir(cwd)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for name in child_env.remove {
        command.env_remove(name);
    }
    for (name, value) in child_env.set {
        command.env(name, value);
    }
    remove_unrelated_cargo_registry_tokens(&mut command, program);
    let mut child = command.spawn().map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            CommandError::NotFound {
                program: program.to_string(),
            }
        } else {
            CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }
        }
    })?;
        args: &[&str],
        cwd: &Path,
        stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        let mut command = std::process::Command::new(program);
        command.args(args).current_dir(cwd);
        remove_env(&mut command, &unrelated_credentials(program));
        remove_unrelated_cargo_registry_tokens(&mut command, program);
        let mut child = command
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
        assert!(out.success());
    }

    #[cfg(unix)]
    #[test]
    fn run_with_timeout_env_filtered_removes_named_variables() {
        let runner = CliCommandRunner;
        let output = runner
            .run_with_timeout_env_filtered(
                "/usr/bin/env",
                &[],
                std::path::Path::new("."),
                Duration::from_secs(5),
                &["PATH"],
            )
            .unwrap();
        assert!(output.success());
        assert!(
            !output.stdout.lines().any(|line| line.starts_with("PATH=")),
            "{}",
            output.stdout
        );
    }

    #[cfg(unix)]

